async function p(t,e={}){const h=e.maxW??1600,g=e.maxH??1600,w=e.quality??.85,c=e.mime??"image/jpeg";if(!t.type.startsWith("image/"))return t;const a=await createImageBitmap(t),m=Math.min(1,h/a.width,g/a.height),o=Math.max(1,Math.round(a.width*m)),i=Math.max(1,Math.round(a.height*m)),n=document.createElement("canvas");n.width=o,n.height=i;const s=n.getContext("2d");if(!s)return t;s.drawImage(a,0,0,o,i);const r=await new Promise(d=>n.toBlob(d,c,w));if(!r)return t;const u=t.name.replace(/\.[^/.]+$/,""),x=c==="image/webp"?"webp":"jpg";return new File([r],`${u}.${x}`,{type:c})}export{p as c};
